// 씨앗 기반 난수 (같은 씨앗 → 같은 순서)
export function makeRandom(seed: number) {
  let s = seed >>> 0;
  return () => (s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32;
}

export function shuffle<T>(arr: T[], rnd: () => number = Math.random): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// 테스트: shuffle(items, makeRandom(42))  → 항상 같은 결과
// 실제:   shuffle(items)                  → 진짜 무작위

// 우리 코드와 바깥의 경계에 얇은 한 겹을 둔다
export type CountApi = { load(): Promise<{ n: number }> };

export const realApi: CountApi = {
  async load() { const r = await fetch('/api/count'); return r.json(); },
};

export async function summary(api: CountApi = realApi): Promise<string> {
  try {
    const { n } = await api.load();
    return n > 0 ? `${n}건` : '없음';
  } catch { return '불러오지 못했습니다'; }
}

// 테스트: summary({ load: async () => { throw new Error('x'); } })

export function expiresIn(
  deadline: number,
  now: number = Date.now(),          // ← 자를 자리
): string {
  const left = deadline - now;
  if (left <= 0) return '만료됨';
  const days = Math.floor(left / 86400000);
  return days > 0 ? `${days}일 남음` : '오늘 마감';
}

// 부르는 쪽: expiresIn(deadline)
// 테스트:   expiresIn(D, D - 1)        → '오늘 마감'
//           expiresIn(D, D + 1)        → '만료됨'   ← 경계를 즉시 시험

